"""Hosted A-share market data and explicitly experimental native forecasts."""
from __future__ import annotations

import json
import logging
import math
import os
import re
import ssl
import urllib.request
from datetime import datetime, timedelta
from typing import Any
from zoneinfo import ZoneInfo

import certifi
import pandas as pd
from fastapi import Depends, FastAPI, HTTPException, Request
from src.api.security import require_auth
from starlette.concurrency import run_in_threadpool

_LOG = logging.getLogger(__name__)
_TZ = ZoneInfo("Asia/Shanghai")

class _NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def _now() -> datetime:
    return datetime.now(_TZ)


def _number(value: Any) -> float:
    number = float(value)
    if not math.isfinite(number):
        raise ValueError("non-finite market value")
    return number


def _source_days(symbol: str) -> tuple[list[dict], dict]:
    # User input is a validated identifier, never a URL; redirects are refused.
    code, exchange = symbol.split(".")
    token = exchange.lower() + code
    url = "https://web.ifzq.gtimg.cn/appstock/app/day/query?code=" + token
    opener = urllib.request.build_opener(
        _NoRedirect(), urllib.request.HTTPSHandler(context=ssl.create_default_context(cafile=certifi.where()))
    )
    request = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0", "Referer": "https://gu.qq.com/"})
    with opener.open(request, timeout=18) as response:
        raw = response.read(2_000_001)
    if len(raw) > 2_000_000:
        raise ValueError("market response too large")
    payload = json.loads(raw)
    if payload.get("code") != 0:
        raise ValueError("market source rejected query")
    stock = payload["data"][token]
    quote = stock["qt"][token]
    as_of = datetime.strptime(quote[30], "%Y%m%d%H%M%S").replace(tzinfo=_TZ).isoformat()
    price, previous = _number(quote[3]), _number(quote[4])
    if min(price, previous) <= 0:
        raise ValueError("quote price unavailable")
    return stock["data"], {
        "price": price, "previous_close": previous, "change": price - previous,
        "change_pct": (price / previous - 1) * 100, "name": str(quote[1]), "as_of": as_of,
    }


def _minute_position(time: str) -> int | None:
    minutes = int(time[:2]) * 60 + int(time[2:])
    if 570 <= minutes <= 690:
        return minutes - 570
    if 780 <= minutes <= 900:
        return minutes - 780 + 121
    return None


def _minute_days(days: list[dict], now: datetime) -> pd.DataFrame:
    rows = []
    for day in days:
        date = datetime.strptime(day["date"], "%Y%m%d").date()
        previous_volume, previous_amount = 0.0, 0.0
        for raw in day["data"]:
            parts = raw.split()
            position = _minute_position(parts[0])
            if position is None:
                continue  # Tencent also includes post-market fixed-price trades after 15:00.
            stamp = datetime.strptime(day["date"] + parts[0], "%Y%m%d%H%M").replace(tzinfo=_TZ)
            if stamp > now:
                continue
            price, volume, amount = map(_number, parts[1:4])
            if price <= 0 or volume < previous_volume or amount < previous_amount:
                raise ValueError("invalid cumulative intraday data")
            rows.append({"trade_date": stamp, "close": price, "volume": volume - previous_volume,
                         "amount": amount - previous_amount, "day": date.isoformat(), "position": position})
            previous_volume, previous_amount = volume, amount
    if not rows:
        return pd.DataFrame()
    return pd.DataFrame(rows).drop_duplicates("trade_date").sort_values("trade_date").reset_index(drop=True)


def _market_state(frame: pd.DataFrame, now: datetime) -> str:
    latest = frame.iloc[-1]["trade_date"]
    if latest.date() != now.date():
        return "closed"
    clock = now.hour * 60 + now.minute
    if 690 < clock < 780:
        return "recess"
    if 570 <= clock <= 900:
        return "open" if (now - latest).total_seconds() <= 300 else "stale"
    return "closed"


def _minute_target(latest: datetime, horizon: int, position: int) -> datetime:
    target = position + horizon
    clock = 570 + target if target <= 120 else 780 + target - 121
    return latest.replace(hour=clock // 60, minute=clock % 60, second=0, microsecond=0)


def _daily_bars(symbol: str, now: datetime, adjusted: bool = False, *,
                end_date: str | None = None, raw_frame: pd.DataFrame | None = None) -> pd.DataFrame:
    from backtest.loaders.tencent_loader import DataLoader

    loader = DataLoader()
    start, end = (now.date() - timedelta(days=1500)).isoformat(), end_date or now.date().isoformat()
    if adjusted:
        result = loader.fetch([symbol], start, end, interval="1D").get(symbol)
        if result is None or result.empty:
            from backtest.loaders.eastmoney_loader import DataLoader as EastmoneyLoader

            result = EastmoneyLoader().fetch([symbol], start, end, interval="1D").get(symbol)
            if result is not None:
                result.attrs.update(source="eastmoney", price_series="eastmoney_fqt1")
    else:
        result = loader._fetch_one(symbol, start, end, forward_adjusted=False)
    if result is None or result.empty:
        return pd.DataFrame()
    result = result[~result.index.duplicated(keep="last")].sort_index()
    result = result.loc[result.index <= pd.Timestamp(end)]
    if adjusted and result.attrs.get("adjustment") != "split_dividend":
        if result.attrs.get("price_series") not in {"qfqday", "eastmoney_fqt1"}:
            raise ValueError("adjusted price source unavailable")
        raw = raw_frame if raw_frame is not None else loader._fetch_one(symbol, start, end, forward_adjusted=False)
        if raw is None or not raw.index.equals(result.index):
            raise ValueError("adjusted return calendars do not align")
        columns = ["open", "high", "low", "close"]
        same = (raw[columns] - result[columns]).abs().le(1e-8).all(axis=1) & raw[columns].gt(0).all(axis=1)
        different = same.index[~same]
        # The native converter may reject older split histories. Only retain
        # the continuous tail where both observed price conventions agree.
        qfq_source = result.attrs.get("source", "tencent")
        result = raw.loc[different[-1]:].iloc[1:].copy() if len(different) else raw.copy()
        if result.empty:
            raise ValueError("adjusted return history unavailable")
        result.attrs = {"adjustment": "none", "return_basis": "raw_equals_qfq",
                        "excluded_history_rows": len(raw) - len(result),
                        "raw_source": "tencent", "qfq_source": qfq_source}
    return result


def market_snapshot(symbol: str, interval: str) -> dict:
    now = _now()
    base = {"symbol": symbol, "interval": interval, "bars": [], "quote": None,
            "trading_date": None, "market_open": False, "market_state": "closed",
            "source": "tencent", "observed_at": now.isoformat(), "volume_unit": "lots", "adjustment": "none"}
    if symbol.endswith(".BJ"):
        return {**base, "status": "unavailable", "reason": "当前免费行情源暂不提供该北交所股票。"}
    try:
        days, quote = _source_days(symbol)
        minutes = _minute_days(days, now)
        if minutes.empty:
            raise ValueError("no trading-session points")
        try:
            from src.api.mona_forecast_store import ForecastStore

            ForecastStore().merge_minutes(symbol, minutes)
        except Exception as exc:
            _LOG.warning("Observed minute history was not cached for %s (%s)", symbol, type(exc).__name__)
        state = _market_state(minutes, now)
        if interval == "intraday":
            date = minutes.iloc[-1]["day"]
            frame = minutes[minutes["day"] == date]
            bars = [{"trade_date": row.trade_date.isoformat(), "close": row.close,
                     "volume": row.volume, "amount": row.amount} for row in frame.itertuples()]
        else:
            frame = _daily_bars(symbol, now)
            if frame.empty:
                raise ValueError("daily history missing")
            date = frame.index[-1].date().isoformat()
            bars = [{"trade_date": stamp.date().isoformat(), **{key: _number(row[key]) for key in
                     ("open", "high", "low", "close", "volume")}} for stamp, row in frame.tail(360).iterrows()]
        if quote["as_of"][:10] != date:
            raise ValueError("quote and series dates do not match")
        return {**base, "status": "ok", "bars": bars, "quote": quote, "trading_date": date,
                "market_open": state == "open", "market_state": state}
    except Exception as exc:
        _LOG.warning("Workbench market unavailable for %s (%s)", symbol, type(exc).__name__)
        return {**base, "status": "unavailable", "reason": "暂时未能读取该股票的行情，请稍后刷新。"}


def register_mona_workbench_market(app: FastAPI) -> None:
    if os.environ.get("VIBE_TRADING_HOSTED") != "1":
        return

    def validate(request: Request, symbol: str, interval: str):
        query = request.query_params
        if set(query) != {"symbol", "interval"} or any(len(query.getlist(key)) != 1 for key in query):
            raise HTTPException(422, "workbench market query fields do not match the contract")
        if not re.fullmatch(r"\d{6}\.(?:SH|SZ|BJ)", symbol) or interval not in {"intraday", "1D"}:
            raise HTTPException(422, "unsupported symbol or interval")

    @app.get("/mona/workbench-market", dependencies=[Depends(require_auth)])
    async def market(request: Request, symbol: str, interval: str) -> dict:
        validate(request, symbol, interval)
        return await run_in_threadpool(market_snapshot, symbol, interval)

    @app.get("/mona/workbench-forecast", dependencies=[Depends(require_auth)])
    async def forecast(request: Request, symbol: str, interval: str) -> dict:
        validate(request, symbol, interval)
        from src.api.mona_forecast_service import request_forecast

        return request_forecast(symbol, interval)

